def smallestStringWithSwaps(s, pairs):
    n = len(s)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, b in pairs:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(i)
    res = list(s)
    for pos in groups.values():
        letters = sorted(s[i] for i in pos)
        for i, ch in zip(pos, letters):
            res[i] = ch
    return "".join(res)
